<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.manage');$id=max(0,(int)($_GET['id']??$_POST['id']??0));$deal=null;if($id){$s=db()->prepare('SELECT * FROM deals WHERE id=?');$s->execute([$id]);$deal=$s->fetch();if(!$deal){http_response_code(404);exit('Negocio no encontrado.');}}$pageTitle=$deal?'Editar negocio':'Nuevo negocio';$clients=db()->query('SELECT id,company_name FROM clients ORDER BY company_name')->fetchAll();$contacts=db()->query("SELECT id,client_id,TRIM(CONCAT(first_name,' ',COALESCE(last_name,''))) name FROM contacts ORDER BY first_name,last_name")->fetchAll();$stages=db()->query('SELECT * FROM pipeline_stages WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$errors=[];$v=fn(string$key,mixed$default='')=>$_POST[$key]??($deal[$key]??$default);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$stageId=(int)($_POST['stage_id']??0);$stage=null;foreach($stages as$st)if((int)$st['id']===$stageId)$stage=$st;if($title==='')$errors[]='El nombre del negocio es obligatorio.';if(!$stage)$errors[]='Selecciona una etapa válida.';$prob=max(0,min(100,(int)($_POST['probability']??($stage['probability']??10))));$currency=(string)($_POST['currency']??'USD');if(!in_array($currency,['CLP','USD','BRL'],true))$currency='USD';$status=$stage?($stage['is_closed_won']?'won':($stage['is_closed_lost']?'lost':'open')):'open';$nextAt=trim((string)($_POST['next_action_at']??''));$nextAt=$nextAt?date('Y-m-d H:i:s',strtotime($nextAt)):null;$data=[$title,max(0,(int)($_POST['client_id']??0))?:null,max(0,(int)($_POST['contact_id']??0))?:null,max(0,(int)($_POST['owner_user_id']??0))?:null,$stageId,max(0,(float)($_POST['amount']??0)),$currency,$prob,($_POST['expected_close_date']??'')?:null,trim((string)($_POST['source']??''))?:null,$status,trim((string)($_POST['next_action']??''))?:null,$nextAt,trim((string)($_POST['notes']??''))?:null,$status==='open'?null:date('Y-m-d H:i:s')];if(!$errors){if($id){db()->prepare('UPDATE deals SET title=?,client_id=?,contact_id=?,owner_user_id=?,stage_id=?,amount=?,currency=?,probability=?,expected_close_date=?,source=?,status=?,next_action=?,next_action_at=?,notes=?,closed_at=? WHERE id=?')->execute([...$data,$id]);}else{db()->prepare('INSERT INTO deals(title,client_id,contact_id,owner_user_id,stage_id,amount,currency,probability,expected_close_date,source,status,next_action,next_action_at,notes,closed_at,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$data,(int)$_SESSION['user_id']]);$id=(int)db()->lastInsertId();}log_activity($deal?'Negocio actualizado':'Negocio creado',(int)($data[1]??0),null,$title);flash('success','Negocio guardado.');redirect('deal_view.php?id='.$id);}}
require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$deal?'Actualizar oportunidad':'Crear oportunidad comercial'?></h2><span class="table-sub">Valor, probabilidad, responsable, próxima acción y fecha estimada de cierre.</span></div><a class="btn btn-light btn-small" href="deals.php">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Nombre del negocio *<input name="title" required value="<?=e($v('title'))?>"></label><label>Etapa<select name="stage_id"><?php foreach($stages as$s):?><option value="<?=$s['id']?>" <?=(int)$v('stage_id',$stages[0]['id']??0)===(int)$s['id']?'selected':''?>><?=e(crm_stage_localized($s))?> · <?=$s['probability']?>%</option><?php endforeach;?></select></label><label>Responsable<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('owner_user_id',$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Cliente<select name="client_id"><option value="0">Sin cliente</option><?php foreach($clients as$c):?><option value="<?=$c['id']?>" <?=(int)$v('client_id',(int)($_GET['client_id']??0))===(int)$c['id']?'selected':''?>><?=e($c['company_name'])?></option><?php endforeach;?></select></label><label>Contacto<select name="contact_id"><option value="0">Sin contacto</option><?php foreach($contacts as$c):?><option value="<?=$c['id']?>" <?=(int)$v('contact_id',(int)($_GET['contact_id']??0))===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Origen<input name="source" value="<?=e($v('source'))?>" placeholder="Web, referido, LinkedIn..."></label><label>Valor<input type="number" step="0.01" min="0" name="amount" value="<?=e($v('amount',0))?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL']as$c):?><option <?=$v('currency','USD')===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><label>Probabilidad %<input type="number" min="0" max="100" name="probability" value="<?=e($v('probability',10))?>"></label><label>Fecha estimada de cierre<input type="date" name="expected_close_date" value="<?=e($v('expected_close_date'))?>"></label><label>Próxima acción<input name="next_action" value="<?=e($v('next_action'))?>" placeholder="Llamar, enviar propuesta..."></label><label>Fecha próxima acción<input type="datetime-local" name="next_action_at" value="<?=e($v('next_action_at')?date('Y-m-d\TH:i',strtotime((string)$v('next_action_at'))):'')?>"></label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="deals.php">Cancelar</a><button class="btn btn-primary">GUARDAR NEGOCIO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
